import { i18n } from 'src/boot/i18n';
import { invalid } from 'src/constants';

export interface DisplayMessage {
  translation_key?: string;
  data?: Record<string, string>;
  message?: string;
}

/**
 * Translate a single string value through i18n.
 * Tries the key as-is first, then lowercased. Returns the original if no translation found.
 */
function translateValue(value: string): string {
  const translated = i18n.t(value, value);
  if (translated !== invalid && translated !== value) return translated as string;
  const lowerTranslated = i18n.t(value.toLowerCase(), value);
  if (lowerTranslated !== invalid && lowerTranslated !== value) return lowerTranslated as string;
  return value;
}

/**
 * Translate data values for use in template interpolation.
 *
 * Mirrors the store's `translateData` logic: each value is run through i18n.t(),
 * and comma-separated lists are translated individually then rejoined.
 * Shared by workflowLogsv2, WorkflowTestResultDialog, and the designer log tooltips.
 */
export function translateData(data: Record<string, any> | undefined): Record<string, string> {
  const result: Record<string, string> = {};
  if (!data || typeof data !== 'object') return result;

  for (const [key, rawValue] of Object.entries(data)) {
    const strValue = Array.isArray(rawValue) ? rawValue.join(', ') : String(rawValue ?? '');

    if (strValue.includes(',')) {
      result[key] = strValue.split(/,\s*/).map(s => s.trim()).map(translateValue).join(', ');
    } else {
      result[key] = translateValue(strValue);
    }
  }
  return result;
}

/**
 * Resolve a partner translation key against the partner_translations dict.
 *
 * Looks up the given locale (falls back to 'en') and interpolates {param}
 * placeholders from `log.data`. Returns null when no translation can be found.
 */
export function resolvePartnerMessage(
  log: { partner_translation_key?: string; data?: Record<string, any> },
  partnerTranslations: Record<string, Record<string, string>> | null | undefined,
  locale: string,
): string | null {
  if (!log.partner_translation_key || !partnerTranslations) return null;

  const shortLocale = locale.split(/[-_]/)[0].toLowerCase();
  const langDict = partnerTranslations[shortLocale] ?? partnerTranslations['en'] ?? {};
  const template = langDict[log.partner_translation_key];
  if (!template) return null;

  return template.replace(/\{(\w+)\}/g, (_: string, key: string) => {
    const val = log.data?.[key];
    return val != null ? String(val) : `{${key}}`;
  });
}

/**
 * Build a display message from a node log entry.
 *
 * Resolution order:
 * 1. Standard `translation_key` → `wf_log_<key>` via i18n
 * 2. `partner_translation_key` → resolved from `partnerTranslations[locale]`
 * 3. Raw `message` string fallback
 *
 * Returns an object that templates can render with either
 * `$t('wf_log_' + translation_key, data)` or plain `{{ message }}`.
 */
export function buildNodeLogMessage(
  log: { translation_key?: string; partner_translation_key?: string; message?: string; data?: Record<string, any> },
  partnerTranslations?: Record<string, Record<string, string>> | null,
  locale?: string,
): DisplayMessage {
  if (log.translation_key) {
    const rawKey = log.translation_key.startsWith('wf_log_')
      ? log.translation_key.substring('wf_log_'.length)
      : log.translation_key;

    const safeData = translateData(log.data);
    const fullKey = 'wf_log_' + rawKey;
    const translated = i18n.t(fullKey, safeData);

    if (translated !== fullKey) {
      return { translation_key: rawKey, data: safeData };
    }
  }

  if (log.partner_translation_key && partnerTranslations) {
    const resolved = resolvePartnerMessage(log, partnerTranslations, locale ?? 'en');
    if (resolved) return { message: resolved };
  }

  return { message: log.message || '' };
}
