import { NodeExecutionStatus, PathResult, NODE_TYPE_TRANSLATION_KEYS } from '../workflow-advanced-models';
import { i18n } from 'src/boot/i18n';

/**
 * Shared status → icon mapping for node execution results.
 * Used by WorkflowTestResultDialog and AdvancedWorkflowViewer.
 */
const NODE_STATUS_ICONS: Record<string, string> = {
  [NodeExecutionStatus.SUCCESS]: 'check_circle',
  [NodeExecutionStatus.ERROR]: 'error',
  [NodeExecutionStatus.FAILED_CONDITION]: 'do_not_disturb_on',
  [NodeExecutionStatus.SKIPPED]: 'skip_next',
};

/**
 * Shared status → Quasar color name mapping.
 */
const NODE_STATUS_COLORS: Record<string, string> = {
  [NodeExecutionStatus.SUCCESS]: 'positive',
  [NodeExecutionStatus.ERROR]: 'negative',
  [NodeExecutionStatus.FAILED_CONDITION]: 'warning',
  [NodeExecutionStatus.SKIPPED]: 'grey',
};

/**
 * Shared status → hex color mapping (for minimap, edges, etc.).
 */
export const NODE_STATUS_HEX_COLORS: Record<string, string> = {
  [NodeExecutionStatus.SUCCESS]: '#4caf50',
  [NodeExecutionStatus.ERROR]: '#f44336',
  [NodeExecutionStatus.FAILED_CONDITION]: '#ff9800',
  [NodeExecutionStatus.SKIPPED]: '#9e9e9e',
};

/**
 * Edge path → hex color mapping.
 */
const EDGE_PATH_COLORS: Record<string, string> = {
  [PathResult.SUCCESS]: '#4caf50',
  [PathResult.FAILED_CONDITION]: '#ff9800',
  [PathResult.ERROR]: '#f44336',
};

/**
 * Designer edge stroke colors by source handle.
 */
export const EDGE_STROKE_COLORS: Record<string, string> = {
  [PathResult.SUCCESS]: '#0282fa',
  [PathResult.FAILED_CONDITION]: '#f5b207',
  [PathResult.ERROR]: '#f44336',
};

/**
 * Minimap / node-type → hex color mapping.
 */
export const NODE_TYPE_COLORS: Record<string, string> = {
  when: '#0282fa',
  start: '#0282fa',
  and: '#4caf50',
  then: '#ff9800',
  delay: '#2196f3',
  all: '#9c27b0',
  any: '#ff5722',
  or: '#e91e63',
  note: '#9e9e9e',
};

/**
 * Control node type → Material icon name.
 */
const CONTROL_NODE_ICONS: Record<string, string> = {
  delay: 'schedule',
  all: 'join_full',
  any: 'flash_on',
  or: 'call_merge',
  note: 'sticky_note_2',
};

export function getControlNodeIcon(nodeType: string): string {
  return CONTROL_NODE_ICONS[nodeType?.toLowerCase()] || 'help';
}

// --- Node-level status display ---

export function getNodeStatusIcon(status: string): string {
  return NODE_STATUS_ICONS[status] || 'help';
}

export function getNodeStatusColor(status: string): string {
  return NODE_STATUS_COLORS[status] || 'grey';
}

export function getNodeStatusHexColor(status: string, fallback = '#9e9e9e'): string {
  return NODE_STATUS_HEX_COLORS[status] || fallback;
}

export function getEdgeColor(sourceHandle: string): string {
  return EDGE_PATH_COLORS[sourceHandle] || '#4caf50';
}

export function getEdgeStrokeColor(sourceHandle: string): string {
  return EDGE_STROKE_COLORS[sourceHandle] || EDGE_STROKE_COLORS[PathResult.SUCCESS];
}

export function getNodeTypeColor(nodeType: string): string {
  return NODE_TYPE_COLORS[nodeType] || '#666';
}

// --- Log entry-level display (individual card/node logs) ---

const LOG_ENTRY_DISPLAY: Record<string, { icon: string; color: string; class: string }> = {
  [PathResult.SUCCESS]: { icon: 'check', color: 'positive', class: 'log-entry-success' },
  [PathResult.FAILED_CONDITION]: { icon: 'do_not_disturb_on', color: 'warning', class: 'log-entry-warning' },
  [PathResult.ERROR]: { icon: 'error', color: 'negative', class: 'log-entry-error' },
};
const LOG_ENTRY_DEFAULT_DISPLAY = { icon: 'info', color: 'grey', class: '' };

export function getLogEntryResult(entry: any): string | null {
  return entry.current_card_result || entry.status || null;
}

export function getLogEntryIcon(entry: any): string {
  return (LOG_ENTRY_DISPLAY[getLogEntryResult(entry)!] ?? LOG_ENTRY_DEFAULT_DISPLAY).icon;
}

export function getLogEntryColor(entry: any): string {
  return (LOG_ENTRY_DISPLAY[getLogEntryResult(entry)!] ?? LOG_ENTRY_DEFAULT_DISPLAY).color;
}

export function getLogEntryClass(entry: any): string {
  return (LOG_ENTRY_DISPLAY[getLogEntryResult(entry)!] ?? LOG_ENTRY_DEFAULT_DISPLAY).class;
}

// --- Node execution helpers (extracted from AdvancedWorkflowViewer) ---

export function isNodeNotExecuted(executionStatus: string | undefined): boolean {
  return !executionStatus || executionStatus === NodeExecutionStatus.SKIPPED;
}

export function getExecutionStatusClass(executionStatus: string | undefined): string {
  if (!executionStatus || executionStatus === NodeExecutionStatus.SKIPPED) {
    return '';
  }
  return `node-status-${executionStatus}`;
}

/**
 * Returns the minimap/badge color for a node, preferring execution status over node type.
 */
export function getNodeColor(node: { data?: { executionStatus?: string; nodeType?: string } }): string {
  const status = node.data?.executionStatus;
  if (status && status !== NodeExecutionStatus.SKIPPED) {
    return getNodeStatusHexColor(status);
  }
  return getNodeTypeColor(node.data?.nodeType || '');
}

// --- Handle usage calculation (extracted from AdvancedWorkflowViewer) ---

export function calculateHandleUsage(
  nodes: { node_id?: string; id?: string }[],
  edges: { source_node_id?: string; source?: string; source_handle?: string; sourceHandle?: string }[],
): Record<string, Set<string>> {
  const usage: Record<string, Set<string>> = {};

  nodes.forEach((node) => {
    const nodeId = node.node_id || node.id || '';
    usage[nodeId] = new Set();
  });

  edges.forEach((edge) => {
    const sourceId = edge.source_node_id || edge.source || '';
    const sourceHandle = edge.source_handle || edge.sourceHandle || PathResult.SUCCESS;
    if (usage[sourceId]) {
      usage[sourceId].add(sourceHandle);
    }
  });

  return usage;
}

// --- Bounds calculation (extracted from AdvancedWorkflowViewer) ---

export function calculateNodeBounds(
  nodes: { position?: { x: number; y: number } }[] | null | undefined,
  padding: number,
  widthOffset: number,
  heightOffset: number,
  fallback: [[number, number], [number, number]],
): [[number, number], [number, number]] {
  if (!nodes || nodes.length === 0) {
    return fallback;
  }

  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

  nodes.forEach((node) => {
    const x = node.position?.x || 0;
    const y = node.position?.y || 0;
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  });

  return [
    [minX - padding, minY - padding],
    [maxX + padding + widthOffset, maxY + padding + heightOffset],
  ];
}

// --- Node data building (extracted from AdvancedWorkflowViewer) ---

export function buildNodeData(
  node: any,
  executionData: Record<string, any>,
  usedHandles: Set<string>,
): any {
  const nodeId = node.node_id || node.id;
  const execData = executionData[nodeId];

  return {
    ...node,
    data: {
      ...node.data,
      executionStatus: execData?.execution_status || execData?.status,
      executionTime: execData?.completion_time || execData?.duration_ms,
      executionOrder: execData?.executionOrder || node.data?.executionOrder,
      error: execData?.error,
      usedHandles: Array.from(usedHandles),
    },
  };
}

// --- Formatting utilities ---

export function formatDelay(seconds: number): string {
  if (seconds >= 3600) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
  } else if (seconds >= 60) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return s > 0 ? `${m}m ${s}s` : `${m}m`;
  }
  return `${seconds}s`;
}

export function formatDuration(ms: number): string {
  if (ms == null) return '-';
  return `${(ms / 1000).toFixed(4)}s`;
}

export function formatNodeType(nodeType: string): string {
  if (!nodeType) return '';
  const key = NODE_TYPE_TRANSLATION_KEYS[nodeType.toLowerCase()] || `wf_${nodeType.toLowerCase()}`;
  return i18n.t(key) as string;
}
