/**
 * Validation error types.
 * Mirrors backend WFValidationErrorTypes(StrEnum).
 */
export enum WFValidationErrorTypes {
  CYCLE = 'cycle',
  NO_TRIGGER = 'no_trigger',
  TRIGGER_HAS_INCOMING = 'trigger_has_incoming',
  INSUFFICIENT_INPUTS = 'insufficient_inputs',
  INVALID_DELAY_CONFIG = 'invalid_delay_config',
  INVALID_SOURCE_HANDLE = 'invalid_source_handle',
  INVALID_TARGET_HANDLE = 'invalid_target_handle',
  TRIGGER_AS_TARGET = 'trigger_as_target',
}

/**
 * Validation warning types.
 * Mirrors backend WFValidationWarningTypes(StrEnum).
 */
export enum WFValidationWarningTypes {
  ORPHAN = 'orphan',
  DUPLICATE_OUTPUT_TARGET = 'duplicate_output_target',
}

/**
 * Node types for workflow nodes.
 * Mirrors backend NodeType(StrEnum).
 */
export enum NodeType {
  WHEN = 'when', // can be used as cardType in fronten for where the card can be found
  AND = 'and', // can be used as cardType in fronten for where the card can be found
  THEN = 'then', // can be used as cardType in fronten for where the card can be found
  START = 'start',
  DELAY = 'delay',
  ALL = 'all',
  ANY = 'any',
  NOTE = 'note',
  OR = 'or',
}

/**
 * VueFlow node types — used as template slot names in the designer.
 * These are frontend-only rendering identifiers, NOT backend NodeType values.
 * They determine which <template #node-{type}> renders the node:
 * - START_NODE: circular play button (start node only)
 * - LOGIC_NODE: renders AdvancedWorkflowCard (WHEN/AND/THEN with cards)
 * - CONTROL_NODE: icon + label (DELAY/ALL/ANY/OR/NOTE without cards)
 */
export const VF_NODE_TYPE = {
  START: 'startNode',
  LOGIC: 'logicNode',
  CONTROL: 'controlNode',
  NOTE: 'noteNode',
} as const;

/**
 * Control node types — nodes that don't have a card attached.
 * Single source of truth for all components.
 */
export const CONTROL_NODE_TYPES = [
  NodeType.START,
  NodeType.DELAY,
  NodeType.ALL,
  NodeType.ANY,
  NodeType.NOTE,
  NodeType.OR,
] as const;

/**
 * Translation key mapping for node types.
 * Control nodes use 'wf_node_X' keys, logic nodes use 'wf_X'.
 */
export const NODE_TYPE_TRANSLATION_KEYS: Record<string, string> = {
  [NodeType.START]: 'wf_node_start',
  [NodeType.DELAY]: 'wf_node_delay',
  [NodeType.ALL]: 'wf_node_wait_all',
  [NodeType.ANY]: 'wf_node_wait_any',
  [NodeType.OR]: 'wf_node_or',
  [NodeType.NOTE]: 'wf_node_note',
  [NodeType.WHEN]: 'wf_when',
  [NodeType.AND]: 'wf_and',
  [NodeType.THEN]: 'wf_then',
};

